# SPOTTER Super-Enrich (workflow 27): identity pivot from corporate to real-world persona.
#
# Operator-initiated, ONE selected person per call (the frontend fans out 1-5).
# The pivot chain, in order:
#   1. resolve the subject and seed from what SPOTTER already knows (AD identity,
#      department, group membership, known emails/phones/addresses)
#   2. LinkedIn /lookup  -> job title, employer, photo, profile URL
#   3. maigret /search   -> username variants (SAM + corp localpart + known
#      personal-email localparts) across the global + regional platform families
#   4. socid /extract    -> mine each discovered profile for real name, bio,
#      contact emails, location, cross-platform links
#   5. harvest KNOWN alternate emails (existing personal_emails + socid emails +
#      LinkedIn) and personal attributes
#   6. Flare exact-email search on EACH discovered alternate email. This honours
#      WF09's own design contract ("search KNOWN alternate emails, not a raw
#      username keyword") -- the username keyword search it deliberately removed
#      bled hundreds of unrelated people onto one person.
#   7. optional Flare firework deep-event pull (reveal_events) -> physical
#      address / IP / device / URLs from stealer-log events
#   8. correlate password reuse + password-format fingerprint across corp and
#      personal accounts
#   9. write the discovered identity back onto the Individual, filling the dossier
#      slots that are read today but written by nobody (personal_emails,
#      personal_phones, personal_location/address, locations_lived, work_history,
#      specialty, social_* URLs), plus super_enriched flags.
#
# Cleartext credential values ride ONLY this synchronous response, and only when
# the caller sets include_credentials. They are NEVER written onto the Individual
# or its super_enrich_summary -- persistence of a cleartext value stays governed
# solely by the FlareBreach.credential_value store that WF09 already created and
# that WF05 gates behind include_credentials. This mirrors WF13's reveal rule.
import sys, os, re, json
sys.path.insert(0, '/data/scripts')
import requests as req
import flowsint_client as fc
from datetime import datetime, timezone
from urllib.parse import urlparse, quote as _url_quote

FLOWSINT_URL = os.environ.get('FLOWSINT_API_URL', 'http://flowsint-api:5001').rstrip('/')
KEY          = os.environ.get('FLOWSINT_API_KEY', '')
MAIGRET_URL  = os.environ.get('MAIGRET_API_URL', 'http://maigret-api:7050').rstrip('/')
LINKEDIN_URL = os.environ.get('LINKEDIN_API_URL', 'http://linkedin-api:7051').rstrip('/')
FLARE_BASE   = 'https://api.flare.io'
FLARE_KEY    = os.environ.get('FLARE_API_KEY', '')
HJ = {'Authorization': f'Bearer {KEY}', 'Content-Type': 'application/json'}
NOW = datetime.now(timezone.utc)
now = NOW.isoformat()

# Runtime-tunable caps (Configuration panel -> Super-Enrich, via SpotterMeta).
# resolve_int falls back to env then the built-in default and never raises, so a
# runner without the settings module still runs with the hardcoded fallbacks.
_caps = {}
try:
    import spotter_settings as _st
    _caps = _st.resolve_many([
        'SUPERENRICH_MAX_USERNAMES', 'SUPERENRICH_MAX_SOCID_URLS',
        'SUPERENRICH_MAX_ALT_EMAILS', 'SUPERENRICH_MAX_EVENTS',
        'SUPERENRICH_MAIGRET_TOP_SITES', 'SUPERENRICH_MAIGRET_TIMEOUT'])
except Exception:
    _caps = {}


def _cap(name, dflt):
    v = _caps.get(name)
    return v if isinstance(v, int) and v > 0 else dflt


MAX_UNAMES    = _cap('SUPERENRICH_MAX_USERNAMES', 5)
MAX_SOCID     = _cap('SUPERENRICH_MAX_SOCID_URLS', 12)
MAX_ALT_EMAIL = _cap('SUPERENRICH_MAX_ALT_EMAILS', 25)
MAX_EVENTS    = _cap('SUPERENRICH_MAX_EVENTS', 15)
MG_TOP        = _cap('SUPERENRICH_MAIGRET_TOP_SITES', 40)
MG_TO         = _cap('SUPERENRICH_MAIGRET_TIMEOUT', 8)
REGION_TOP    = 40
SOCID_TIMEOUT = 15

item = _items[0].get('json', {}) if _items else {}
body = item.get('body', item) if isinstance(item.get('body'), dict) else item
if not isinstance(body, dict):
    body = {}

SK = (body.get('sketch_id') or '') or os.environ.get('FLOWSINT_SKETCH_ID', '')
entity = body.get('entity', {}) if isinstance(body.get('entity'), dict) else {}
subj_id    = str(entity.get('id') or body.get('entity_id') or '').strip()
subj_label = str(entity.get('label') or body.get('entity_label') or '').strip()
req_company = str(body.get('company') or '').strip()
company_domain = str(body.get('company_email_domain') or '').strip().lower()
INCLUDE_CREDS = bool(body.get('include_credentials'))
REVEAL_EVENTS = bool(body.get('reveal_events'))

notes = []
errors = []
sources = {'linkedin': False, 'maigret': 0, 'socid': 0, 'flare_emails': 0, 'flare_events': 0}


# ── Egress proxy/opsec envelope (identical shape to WF03/WF13) ─────────────────
def _proxy_url_from_envelope(proxy):
    if not isinstance(proxy, dict):
        return ''
    if proxy.get('enabled') is False:
        return ''
    ptype = str(proxy.get('type') or '').strip().lower()
    if ptype == 'http':
        return str(proxy.get('http_url') or '').strip()
    if ptype in ('socks5', 'tor'):
        direct = str(proxy.get('socks_url') or '').strip()
        if direct:
            return direct
        socks = proxy.get('socks') if isinstance(proxy.get('socks'), dict) else {}
        host = str(socks.get('host') or '').strip()
        port = str(socks.get('port') or '').strip()
        if not host or not port:
            return ''
        user = str(socks.get('username') or '').strip()
        pw = str(socks.get('password') or '').strip()
        auth = ''
        if user:
            auth = _url_quote(user, safe='')
            if pw:
                auth += ':' + _url_quote(pw, safe='')
            auth += '@'
        return 'socks5h://' + auth + host + ':' + port
    return ''


proxy_cfg = body.get('proxy') if isinstance(body.get('proxy'), dict) else {}
opsec_cfg = body.get('opsec') if isinstance(body.get('opsec'), dict) else {}
PROXY_URL = _proxy_url_from_envelope(proxy_cfg)
UA = str(opsec_cfg.get('user_agent') or '').strip()[:256]

VALID_REGIONS = ('us', 'ru', 'cn')
_raw_regions = body.get('social_regions')
if not isinstance(_raw_regions, list):
    _raw_regions = []
_want = {str(x or '').strip().lower() for x in _raw_regions}
REGIONS = [r for r in VALID_REGIONS if r in _want]


def _resp(payload):
    payload.setdefault('sketch_id', SK)
    payload.setdefault('subject', {'id': subj_id, 'label': subj_label})
    payload.setdefault('sources', sources)
    payload.setdefault('notes', notes)
    payload.setdefault('errors', errors[:50])
    return [{'json': payload}]


if not SK:
    return _resp({'status': 'error', 'error': 'no sketch_id in request'})


# ── 1. Resolve subject + seed "what we know" ──────────────────────────────────
def _list_prop(v):
    if isinstance(v, list):
        return [str(x).strip() for x in v if str(x).strip()]
    if isinstance(v, str) and v.strip():
        s = v.strip()
        if s[:1] in ('[', '{'):
            try:
                j = json.loads(s)
                if isinstance(j, list):
                    return [str(x).strip() for x in j if str(x).strip()]
            except Exception:
                pass
        return [s]
    return []


subj = None
try:
    if subj_id:
        subj = fc.get_node_by_id(subj_id, sketch_id=SK)
    if subj is None and subj_label:
        for n in fc.get_nodes_by_type(['individual'], sketch_id=SK):
            if str(n.get('nodeLabel') or '') == subj_label:
                subj = n
                break
except Exception as e:
    errors.append('subject resolve: ' + str(e))

if subj is None:
    return _resp({'status': 'error', 'error': 'subject individual not found in sketch'})

sp = subj.get('nodeProperties') or subj.get('data') or {}
subj_id = subj.get('id') or subj_id
subj_label = subj.get('nodeLabel') or subj_label

fn = str(sp.get('first_name') or '').strip()
ln = str(sp.get('last_name') or '').strip()
full_name = str(sp.get('full_name') or sp.get('display_name') or '').strip()
if not full_name and fn and ln:
    full_name = fn + ' ' + ln
corp_email = str(sp.get('email') or '').strip().lower()
sam = str(sp.get('sam_account_name') or sp.get('username') or '').strip().lower()
department = str(sp.get('department') or '').strip()
company = req_company or str(sp.get('employer') or sp.get('linkedin_employer') or '').strip()

known_personal = [e.lower() for e in _list_prop(sp.get('personal_emails')) if '@' in e]
known_phones = _list_prop(sp.get('personal_phones'))
for _pk in ('phone', 'mobile', 'telephonenumber'):
    _pv = str(sp.get(_pk) or '').strip()
    if _pv and _pv not in known_phones:
        known_phones.append(_pv)
known_addresses = _list_prop(sp.get('addresses')) or _list_prop(sp.get('personal_address'))

# Group membership is the closest thing to an org chart: there is no manager edge
# and SharpHound writes no AD title, so "org context" = department + groups.
groups = []
try:
    _me = fc.get_edges_by_type('MEMBER_OF', sketch_id=SK,
                               source_label='individual', target_label='organization')
    _org_ids = {e.get('target') for e in _me if e.get('source') == subj_id}
    if _org_ids:
        for o in fc.get_nodes_by_type(['organization'], sketch_id=SK, properties=['name']):
            if o.get('id') in _org_ids:
                nm = str((o.get('nodeProperties') or {}).get('name') or o.get('nodeLabel') or '').strip()
                if nm:
                    groups.append(nm)
        groups = sorted(set(groups))[:40]
except Exception as e:
    errors.append('groups: ' + str(e))


# ── Flowsint write helpers (SocialProfile create + HAS_PROFILE) ────────────────
def _add_sp(platform, username, url, extra=None):
    sp_label = platform.title() + ':' + str(username)
    props = {'platform': platform, 'username': str(username), 'url': url,
             'source': 'super-enrich', 'discovered_at': now}
    if extra:
        props.update({k: v for k, v in extra.items() if v not in (None, '')})
    try:
        r = req.post(FLOWSINT_URL + '/api/sketches/' + SK + '/nodes/add', headers=HJ,
                     json={'id': None, 'nodeLabel': sp_label, 'nodeType': 'SocialProfile',
                           'nodeMetadata': {}, 'nodeProperties': props}, timeout=20)
        r.raise_for_status()
        j = r.json() or {}
        return (j.get('node') or j).get('id', '')
    except Exception:
        return ''


def _link(src, tgt, lbl):
    if not src or not tgt:
        return
    try:
        req.post(FLOWSINT_URL + '/api/sketches/' + SK + '/relations/add', headers=HJ,
                 json={'source': src, 'target': tgt, 'label': lbl, 'type': 'one-way'}, timeout=20)
    except Exception:
        pass


def _useful_profile(url, username):
    try:
        u = urlparse(url or '')
        if not u.netloc:
            return False
        path = (u.path or '').strip('/')
        if not path and not u.query:
            return False
        if username and str(username).lower() in (url or '').lower():
            return True
        return len(path) >= 2
    except Exception:
        return True


# Identity attributes discovered along the way.
social_found = []          # {platform, url, display_name}
socid_emails = set()
socid_locations = []
real_names = []
work_history = []
specialty = ''
li = None

# ── 2. LinkedIn ───────────────────────────────────────────────────────────────
if full_name and ' ' in full_name:
    try:
        lr = req.post(LINKEDIN_URL + '/lookup',
                      json={'full_name': full_name, 'email': corp_email or None,
                            'company': company or None}, timeout=45)
        if lr.ok:
            d = lr.json() or {}
            if d.get('found') and d.get('url'):
                li = d
                slug = d['url'].rstrip('/').split('/in/')[-1] or full_name
                spid = _add_sp('linkedin', slug, d['url'],
                               {'job_title': d.get('job_title'), 'employer': d.get('employer'),
                                'display_name': d.get('display_name') or full_name,
                                'photo_url': d.get('photo_url'),
                                'photo_source': 'linkedin' if d.get('photo_url') else None,
                                'confidence': d.get('confidence')})
                _link(subj_id, spid, 'HAS_PROFILE')
                social_found.append({'platform': 'linkedin', 'url': d['url'],
                                     'display_name': d.get('display_name')})
                sources['linkedin'] = True
                if d.get('employer') and not company:
                    company = str(d.get('employer'))
    except Exception as e:
        errors.append('linkedin: ' + str(e))


# ── socid-extractor field map (same split as WF03) ────────────────────────────
_SOCID_MAP = {
    'fullname': 'display_name', 'name': 'display_name', 'real_name': 'display_name',
    'bio': 'bio', 'about': 'bio', 'description': 'bio',
    'location': 'location', 'city': 'location',
    'image': 'photo_url', 'avatar': 'photo_url', 'photo': 'photo_url',
    'email': 'profile_emails',
}


def _socid_updates(xd):
    data = xd.get('data') or {}
    upd = {}
    for k, v in data.items():
        if v in (None, '', [], {}):
            continue
        dest = _SOCID_MAP.get(str(k).lower())
        if dest == 'profile_emails':
            vals = [str(x) for x in v] if isinstance(v, list) else [str(v)]
            upd['nodeProperties.profile_emails'] = vals
            for e in vals:
                if '@' in e:
                    socid_emails.add(e.strip().lower())
        elif dest == 'location':
            loc = str(v)[:200]
            upd.setdefault('nodeProperties.location', loc)
            if loc and loc not in socid_locations:
                socid_locations.append(loc)
        elif dest == 'display_name':
            nm = str(v)[:200]
            upd.setdefault('nodeProperties.display_name', nm)
            if nm and nm not in real_names:
                real_names.append(nm)
        elif dest:
            upd.setdefault('nodeProperties.' + dest, str(v)[:2000])
        else:
            safe = re.sub(r'[^a-z0-9_]', '_', str(k).lower()).strip('_')
            if safe:
                upd['nodeProperties.socid_' + safe] = v if isinstance(v, (int, float, bool)) else str(v)[:2000]
    if not upd:
        return {}
    upd['nodeProperties.socid_enriched'] = True
    upd['nodeProperties.socid_enriched_at'] = now
    if xd.get('scheme'):
        upd['nodeProperties.socid_scheme'] = xd['scheme']
    return upd


sp_mined = set()


def _mine_profile(sp_id, sp_url):
    if not sp_id or not sp_url or sp_id in sp_mined:
        return False
    sp_mined.add(sp_id)
    payload = {'url': sp_url, 'timeout': SOCID_TIMEOUT}
    if PROXY_URL:
        payload['proxy_url'] = PROXY_URL
    if UA:
        payload['user_agent'] = UA
    try:
        xr = req.post(MAIGRET_URL + '/extract', json=payload, timeout=SOCID_TIMEOUT * 3 + 20)
        if not xr.ok:
            return False
        xd = xr.json() or {}
        if not xd.get('found'):
            return False
        upd = _socid_updates(xd)
        if not upd:
            return False
        req.put(FLOWSINT_URL + '/api/sketches/' + SK + '/nodes/edit', headers=HJ,
                json={'nodeId': sp_id, 'updates': upd}, timeout=20)
        return True
    except Exception:
        return False


# ── 3. Maigret discovery (username variants) ──────────────────────────────────
unames = []
for u in [sam, (corp_email.split('@')[0] if '@' in corp_email else '')] + \
         [e.split('@')[0] for e in known_personal]:
    u = str(u or '').strip().lower()
    if u and u not in unames and not u.endswith('$') and len(u) >= 3:
        unames.append(u)
unames = unames[:MAX_UNAMES]

seen = set()
discovered = []


def _sweep(u, tags, top):
    payload = {'username': u, 'timeout': MG_TO, 'top_sites': top}
    if tags:
        payload['tags'] = tags
    if PROXY_URL:
        payload['proxy_url'] = PROXY_URL
    if UA:
        payload['user_agent'] = UA
    mr = req.post(MAIGRET_URL + '/search', json=payload, timeout=MG_TO * 4 + 90)
    if not mr.ok:
        return
    for prof in (mr.json().get('profiles') or []):
        pk = (str(prof.get('platform')) + ':' + str(prof.get('username'))).lower()
        if pk in seen:
            continue
        seen.add(pk)
        if not _useful_profile(prof.get('url', ''), prof.get('username', '')):
            continue
        spid = _add_sp(prof['platform'], prof['username'], prof['url'],
                       {'category': prof.get('category'), 'via_username': u,
                        'region': tags or None})
        _link(subj_id, spid, 'HAS_PROFILE')
        social_found.append({'platform': prof['platform'], 'url': prof['url'],
                             'display_name': None})
        sources['maigret'] += 1
        if spid:
            discovered.append((spid, prof['url']))


for u in unames:
    try:
        _sweep(u, '', MG_TOP)
    except Exception as e:
        errors.append('maigret[' + u + ']: ' + str(e))
    for rg in REGIONS:
        try:
            _sweep(u, rg, REGION_TOP)
        except Exception:
            pass

# ── 4. socid extraction on discovered profiles ────────────────────────────────
for sp_id, sp_url in discovered[:MAX_SOCID]:
    if _mine_profile(sp_id, sp_url):
        sources['socid'] += 1


# ── 5. Harvest KNOWN alternate emails + attributes ────────────────────────────
alt_emails = set()
for e in known_personal:
    alt_emails.add(e)
for e in socid_emails:
    alt_emails.add(e)
# The subject's own corp email is searched by WF09; SUPER-ENRICH targets the
# newly-discovered accounts. Keep it out of the personal set but remember it so
# the corp side is available for reuse correlation below.
alt_emails.discard(corp_email)
alt_emails = sorted(alt_emails)[:MAX_ALT_EMAIL]

locations_lived = []
for loc in socid_locations:
    if loc not in locations_lived:
        locations_lived.append(loc)
if li and li.get('job_title'):
    specialty = ''  # derive below from title if desired
primary_location = locations_lived[0] if locations_lived else ''


# ── 6. Flare: token + exact-email search on each discovered email ─────────────
_HASH_ALGOS = ('md5', 'sha1', 'sha224', 'sha256', 'sha384', 'sha512', 'bcrypt',
               'scrypt', 'argon2', 'ntlm', 'pbkdf2', 'crypt', 'phpass', 'mysql')
_HEX_BY_LEN = {32: 'md5', 40: 'sha1', 56: 'sha224', 64: 'sha256',
               96: 'sha384', 128: 'sha512'}


def _classify_cred(value, reported_type):
    rt = str(reported_type or '').strip().lower()
    v = str(value or '').strip()
    if not v:
        return (rt or 'none'), False
    if rt in ('plain', 'plaintext', 'cleartext'):
        return 'plaintext', True
    if rt and rt not in ('unknown', 'none', 'null') and any(a in rt for a in _HASH_ALGOS):
        return rt, False
    if v.startswith(('$2a$', '$2b$', '$2y$')):
        return 'bcrypt', False
    if v.startswith('$argon2'):
        return 'argon2', False
    if v.startswith('$6$'):
        return 'sha512crypt', False
    if v.startswith('$1$'):
        return 'md5crypt', False
    if all(c in '0123456789abcdefABCDEF' for c in v) and len(v) in _HEX_BY_LEN:
        return _HEX_BY_LEN[len(v)], False
    return 'plaintext', True


def _is_stealer(event_type):
    return 'stealer' in str(event_type or '').lower()


def _s(v, default=''):
    if isinstance(v, dict):
        return str(v.get('name') or v.get('type') or v.get('value') or default)
    return str(v) if v else default


flare_token = ''
flare_status = 'not_attempted'
if not FLARE_KEY:
    flare_status = 'missing_api_key'
    notes.append('FLARE_API_KEY not set — breach pivot skipped')
else:
    try:
        tr = req.post(FLARE_BASE + '/tokens/generate', headers={'Authorization': FLARE_KEY}, timeout=15)
        if tr.status_code >= 400:
            flare_status = 'auth_error_' + str(tr.status_code)
            notes.append('Flare auth HTTP ' + str(tr.status_code))
        else:
            flare_token = (tr.json() or {}).get('token', '')
            flare_status = 'ok' if flare_token else 'auth_error'
    except Exception as e:
        flare_status = 'auth_error'
        errors.append('flare auth: ' + str(e))


def _flare_search_email(email):
    out = []
    if not flare_token:
        return out
    cursor = None
    for _ in range(20):
        b = {'size': 200, 'query': {'type': 'email', 'email': email}}
        if cursor:
            b['from'] = cursor
        try:
            r = req.post(FLARE_BASE + '/astp/v2/credentials/_search',
                         headers={'Authorization': 'Bearer ' + flare_token,
                                  'Content-Type': 'application/json'},
                         json=b, timeout=30)
        except Exception as e:
            errors.append('flare search ' + email + ': ' + str(e))
            break
        if r.status_code >= 400:
            if r.status_code == 403:
                notes.append('Flare ASTP not enabled (403)')
            else:
                errors.append('flare search ' + email + ': HTTP ' + str(r.status_code))
            break
        try:
            data = r.json()
        except Exception:
            break
        items = data.get('items') or data.get('hits') or []
        out.extend(items)
        cursor = data.get('next')
        if not cursor or not items:
            break
    return out


# Preload existing FlareBreach records on the subject (the corp/known side) so the
# reuse correlation can see corp-vs-personal without re-querying Flare for the
# corp email (WF09 owns that address) and so we do not recreate existing nodes.
corp_creds = []            # {account, value, hash_type, plaintext, source, event_type}
existing_bids = set()
try:
    _fb = fc.get_nodes_by_type('FlareBreach', sketch_id=SK,
                               properties=['breach_id', 'credential_value', 'identity_name',
                                           'event_type', 'source', 'hash_type', 'password_exposed'])
    _fb_by_id = {n['id']: (n.get('nodeProperties') or {}) for n in _fb}
    for e in fc.get_edges_by_type('HAS_BREACH', sketch_id=SK,
                                  source_label='individual', target_label='FlareBreach'):
        if e.get('source') != subj_id:
            continue
        p = _fb_by_id.get(e.get('target'))
        if not p:
            continue
        bid = str(p.get('breach_id') or '')
        if bid:
            existing_bids.add(bid)
        val = str(p.get('credential_value') or '')
        htype = str(p.get('hash_type') or '')
        _, plain = _classify_cred(val, htype)
        corp_creds.append({'account': str(p.get('identity_name') or corp_email),
                           'value': val, 'hash_type': htype, 'plaintext': plain,
                           'source': str(p.get('source') or ''),
                           'event_type': str(p.get('event_type') or ''), 'side': 'corp'})
except Exception as e:
    errors.append('breach preload: ' + str(e))


# Search Flare for each discovered personal/alternate email and import the hits.
personal_creds = []
breach_report = []
imported_breaches = 0
firework_targets = []
for email in alt_emails:
    hits = _flare_search_email(email)
    if hits:
        sources['flare_emails'] += 1
    for b in hits:
        src_obj = b.get('source') if isinstance(b.get('source'), dict) else {}
        breach_id = str(b.get('id') or b.get('credential_hash') or '')
        event_type = (_s(b.get('event_type'))
                      or str(src_obj.get('id') or b.get('source_id') or '')
                      or 'leaked_credentials')
        source = _s(b.get('source')) or str(src_obj.get('name') or b.get('source_id') or '')
        identity = _s(b.get('identity_name')) or email
        domain = _s(b.get('domain'))
        hash_type_reported = _s(b.get('hash_type'))
