# ── 8. Correlation: password reuse + format fingerprint ───────────────────────
def _fmt_fingerprint(v):
    v = str(v or '')
    if not v:
        return {}
    classes = []
    if re.search(r'[a-z]', v):
        classes.append('lower')
    if re.search(r'[A-Z]', v):
        classes.append('upper')
    if re.search(r'[0-9]', v):
        classes.append('digit')
    if re.search(r'[^A-Za-z0-9]', v):
        classes.append('symbol')
    mask = re.sub(r'[A-Za-z]+', 'W', v)
    mask = re.sub(r'[0-9]+', 'D', mask)
    mask = re.sub(r'[^A-Za-z0-9]+', 'S', mask)
    m = re.match(r'^([A-Za-z]+)(\d{2,4})?([^A-Za-z0-9]+)?$', v)
    base = (m.group(1).lower() if m and m.group(1) else '')
    year = (m.group(2) if m and m.group(2) else '')
    return {'length': len(v), 'classes': classes, 'mask': mask, 'base': base, 'year': year}


