# Format families: same structural mask + base word across 2+ distinct accounts.
by_fmt = {}
fingerprints = {}
for c in plain_creds:
    fp = _fmt_fingerprint(c['value'])
    key = (fp.get('mask', ''), fp.get('base', ''))
    if fp.get('base'):
        by_fmt.setdefault(key, set()).add(c['account'] or '?')
    fingerprints.setdefault(c['account'] or '?', fp)
format_families = [{'mask': k[0], 'base': k[1], 'accounts': sorted(v)}
                   for k, v in by_fmt.items() if len(v) >= 2]

